insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('afe9db16-1b83-4292-ba6f-e10ecbe6ac93', 'de', 'Was ist sozialer Status, wenn es um Anziehung geht?', '["Finanzieller Erfolg oder Berühmtheit", "Allein das Aussehen", "Wie viele Freunde du mitbringst", "Der Wert, den andere dir zuschreiben, je nachdem, wie sie auf dich reagieren"]'::jsonb, 'Status ist, wie der Raum auf dich reagiert. Das zeigt, dass du sozial geschätzt wirst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('746b1fe5-9312-4688-8acf-78d313a7752a', 'de', 'Du kommst in eine Location und stellst dich ein paar Leuten vor. Später sprichst du sie an. Was hat geholfen?', '["Sie ist offener, weil du schon sozialen Beweis aufgebaut hast", "Nichts. Status beeinflusst nicht, wie offen sie ist", "Du musst trotzdem noch niedrigen Status überwinden", "Die Ansprache wirkt erzwungen"]'::jsonb, 'Positive Begegnungen heben deinen Status, und sie ist offener für dich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c790b664-f094-409a-9440-448401e0ec8e', 'de', 'Wie kann man in einer neuen Umgebung schnell sozialen Status aufbauen?', '["Leute einander vorstellen", "Respektvoll mit Personal oder Gastgebern ins Gespräch kommen", "Sich ausschließlich auf eine Person konzentrieren", "Positiv zur Stimmung der Gruppe beitragen"]'::jsonb, 'Wer etwas zum sozialen Miteinander beiträgt, gewinnt schneller an Status, als wer nur einer Person nachläuft.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9d799275-6cc6-4451-9db7-bfb0e563f9bc', 'de', 'Was macht einen Mann im Gespräch wirklich interessant?', '["Ein Leben, aus dem Geschichten und eigene Sichtweisen entstehen", "Starke Meinungen", "Auf Knopfdruck witzig sein", "Selbstbewusst über sich reden"]'::jsonb, 'Ein interessantes Leben bringt echte Erlebnisse hervor, und die ziehen Menschen ganz natürlich an.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d8654d59-aeba-4ca6-b2c9-c6824582ae10', 'de', 'Woran erkennst du, dass jemand ein interessantes Leben führt?', '["Die Person hat ganz natürlich Geschichten aus echten Erlebnissen", "Sie stellt aus echter Neugier bessere Fragen", "Sie spricht leidenschaftlich über laufende Projekte oder Interessen", "Alle oben genannten"]'::jsonb, 'Ein interessantes Leben bringt echte Erlebnisse hervor, und die ziehen Menschen ganz natürlich an.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8dd4c710-136c-4930-a752-e6a21ba5f5ac', 'de', 'Wie verändert ein interessantes Leben deine Gespräche?', '["Reden wird zur Vorstellung", "Es liefert ganz natürlich Themen, ohne dass du suchen musst", "Echte Erlebnisse geben dir eine anziehende Energie"]'::jsonb, 'Ein interessantes Leben sorgt für mühelose, fesselnde Gespräche.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a96beb76-cf2b-44bb-8339-887ee43c1e0e', 'de', 'Warum hilft etwas Geheimnisvolles bei der Anziehung?', '["Ungewissheit hält sie gedanklich dabei und neugierig", "Das Gehirn achtet mehr auf das, was es nicht ganz durchschaut", "Sie hat Raum, dich zu entdecken, statt mit Infos überschüttet zu werden", "Alle oben genannten"]'::jsonb, 'Etwas Geheimnisvolles hält die Aufmerksamkeit wach, weil es Raum für Neugier und Entdeckung lässt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('87f62533-abcc-4fdd-ab12-24b45f5f4be0', 'de', 'Sie fragt, was du beruflich machst. Welche Antwort ist am geheimnisvollsten?', '["Deinen Job und deine Projekte ausführlich erklären", "„Ein bisschen dies und das, meistens was Kreatives“ sagen und dann nach ihr fragen", "Deinen kompletten Werdegang aufzählen", "„Nichts Spannendes“ sagen und das Thema wechseln"]'::jsonb, 'Verrat gerade so viel, dass es neugierig macht, und lass Raum für ihre Neugier.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f45fc9f5-e0a3-4d7b-87bc-840a0f414623', 'de', 'Was passiert, wenn du dich am Anfang des Gesprächs zu sehr erklärst?', '["Ihre Fantasie bleibt aktiv", "Es bleibt nichts mehr, was sie entdecken oder sich fragen könnte", "Die Neugier lässt nach, weil das Bild vollständig ist"]'::jsonb, 'Wer alles verrät, nimmt die Ungewissheit raus, und sie ist gedanklich weniger dabei.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59011032-6b21-4d79-aaf3-ebe1fcb14211', 'de', 'Wie beeinflusst dein Freundeskreis dein Selbstbewusstsein bei Frauen?', '["Dein Umfeld bestimmt, ob sich ein Verhalten normal oder seltsam anfühlt", "Freunde bringen dir direkt bei, wie Anziehung funktioniert", "Selbstbewusstsein ist biologisch ansteckend", "Frauen ziehen Gruppen Einzelnen vor"]'::jsonb, 'Dein Umfeld fördert entweder deine Entwicklung oder bestärkt dein Zögern.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('80bb97c5-90cf-434a-a890-08a1daa36c04', 'de', 'Was passiert, wenn deine Freunde nicht ausgehen und keine neuen Leute kennenlernen?', '["Deine Lust, Leute anzusprechen, lässt mit der Zeit nach", "Dein Umfeld drängt dich zum Nichtstun", "Ansprechen fühlt sich irgendwann ungewöhnlich und unnötig an", "Alle oben genannten"]'::jsonb, 'Umgib dich mit Menschen, die aktiv sind und dich zum Handeln ermutigen statt zum Ausweichen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3863647b-81d5-4ab3-9b63-30861c071216', 'de', 'Was macht ein Freundeskreis, der dich wachsen lässt, typischerweise?', '["Er gibt dir einen Schubs, wenn du zögerst", "Er feiert die Mühe, nicht nur das Ergebnis", "Er sorgt dafür, dass du bequem und zufrieden bleibst", "Er schafft Gelegenheiten, neue Leute kennenzulernen"]'::jsonb, 'Wer mit aktiven Menschen unterwegs ist, ergreift eher die Initiative, statt auszuweichen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5b78be7b-c378-4416-a5d7-3266ab3c3dfc', 'de', 'Wie baust du mehr soziale Kontakte in deinen Alltag ein?', '["Auch mal zusagen, wenn du müde bist", "Losgehen, auch wenn Zuhausebleiben leichter wäre", "Gruppen beitreten, auch wenn du nicht sicher bist, ob sie dir gefallen", "Alle oben genannten"]'::jsonb, 'Mehr soziale Kontakte entstehen durch viele kleine Entscheidungen, hinzugehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('49c55c64-36bd-4961-9847-6467136116c3', 'de', 'Du bist zu einem Event eingeladen, bist aber müde. Was hat Vorrang?', '["Jedes Mal gemütlich zu Hause bleiben", "Trotzdem hingehen, um Gelegenheiten zu schaffen", "Warten, bis du perfekt in Form bist", "Absagen, um erzwungene Gespräche zu vermeiden"]'::jsonb, 'Wenn du trotz Müdigkeit zusagst, hast du mehr Begegnungen und mehr mögliche Kontakte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dbe59913-e0d6-4e3f-a500-abe814b9551c', 'de', 'Wie vervielfachen sich soziale Kontakte mit der Zeit?', '["Eine Person kann zu vielen anderen führen", "Einladungen öffnen neue Umfelder", "Aus jeder Begegnung wird etwas"]'::jsonb, 'Ein Kontakt kann Dutzende Gelegenheiten über Umwege öffnen. Geh raus unter Leute.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a683dd8f-530d-4c64-a862-57d8f10be86b', 'de', 'Welche Übungsgelegenheiten gibt es in deinem Alltag vor Ort?', '["Kurzer Plausch mit dem Barista in deinem Stammcafé", "Kurzer Kontakt mit jemandem, den du regelmäßig im Fitnessstudio siehst", "Eine Bemerkung in der Schlange an der Supermarktkasse", "Alle oben genannten"]'::jsonb, 'Kleine Begegnungen vor Ort senken den Druck und machen dich beständiger.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bb06d0a0-4845-4ac7-80b4-cca9c98be6a3', 'de', 'Du siehst jeden Morgen denselben Barista. Wie könntest du das zum Üben nutzen?', '["Lieber auf einen Abend in einer Bar warten", "Nichts sagen, damit es bequem bleibt", "Eine kleine Bemerkung machen oder kurz plaudern"]'::jsonb, 'Tägliche Begegnungen ohne Druck bauen ganz natürlich Sicherheit und Können auf.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('219c6ef8-a1ff-4dbe-8af3-fa8686d0e3c1', 'de', 'Was ist der größte Vorteil vom Üben im Alltag gegenüber Bars und Clubs?', '["Es beschränkt Begegnungen aufs Wochenende", "Es macht deine alltägliche Umgebung zum Trainingsplatz", "Es erfordert für jede Übung einen eigenen Ausflug", "Es hält den Einsatz hoch, für bessere Ergebnisse"]'::jsonb, 'Alltägliche Orte bieten endlos viele Gelegenheiten ohne Druck.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('614a2ff0-a42d-4640-8fe2-752885cd8ed4', 'de', 'Was ist der „Heimvorteil“ in sozialen Situationen?', '["Selbstbewusstsein, weil du auf vertrautem Terrain bist", "Sozialer Beweis und Status, weil man dich als Stammgast kennt", "Der Vorteil, dass du dich in der Location und mit den Leuten auskennst", "Ein Wohlgefühl, das Ansprechen weniger beängstigend macht"]'::jsonb, 'Heimvorteil heißt: sozialer Beweis und Status, weil man dich als Stammgast kennt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('91be9da9-35e2-4ee6-a859-ebc43437dadd', 'de', 'Was signalisiert es anderen, wenn man dich als Stammgast kennt?', '["Du gehörst eindeutig hierher", "Andere haben dich schon akzeptiert und für gut befunden", "Du hast mehr Geld oder Status als normale Gäste", "Man kann gefahrlos mit dir ins Gespräch kommen"]'::jsonb, 'Dazugehören, von anderen für gut befunden und als harmlos erlebt: Das ist der Heimvorteil.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7755c8f9-1d23-4c93-b84c-9bb4a6f5047f', 'de', 'Wie baust du dir im Fitnessstudio einen Heimvorteil auf?', '["Regelmäßig zu ähnlichen Zeiten kommen, damit man dich kennt", "Kurze, freundliche Momente mit Personal und Stammgästen", "Nur mit Leuten reden, an denen du romantisch interessiert bist", "Bekannte Gesichter grüßen, die du schon mal gesehen hast"]'::jsonb, 'Regelmäßigkeit, freundliche Kontakte zu Personal und Stammgästen und bekannte Gesichter grüßen: So baust du deinen Heimvorteil auf.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4a4122bd-a43e-4662-aef4-08635258b40c', 'de', 'Welche Einstellung hilft am meisten, oft anzusprechen?', '["Jede Wiederholung bringt deinem Nervensystem etwas Positives bei", "Jedes Ansprechen muss zu etwas führen", "Ergebnisse zählen mehr als die Übung", "Unbehagen vermeiden, wo es geht"]'::jsonb, 'Jede Begegnung zählt als Training, egal wie sie ausgeht.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('659f514c-7bf3-425d-9c1e-cf5df2bb69ef', 'de', 'Ein Ansprechen fühlt sich flach an, und es kommt nichts dabei raus. Wie solltest du das sehen?', '["Als wertvolle Wiederholung, die dich daran gewöhnt", "Als Versagen, das die Angst verstärkt", "Als Beweis, dass du bessere Sprüche brauchst", "Als Grund, für heute aufzuhören"]'::jsonb, 'Jede Begegnung, egal wie sie ausgeht, bringt dich beim Lernen weiter.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4e225e86-4aa9-4111-b01c-711e3725c89f', 'de', 'Was sorgt dafür, dass du wirklich oft ansprichst?', '["Eine kleine Begegnung pro Tag", "Warten, bis du dich selbstbewusst fühlst", "Regelmäßige Wiederholungen ohne Druck", "Nur ansprechen, wenn die Anziehung groß ist"]'::jsonb, 'Regelmäßigkeit und Häufigkeit zählen mehr als Intensität.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b9f59424-635d-4624-ad50-aa3dd25f6855', 'de', 'Was bewirkt regelmäßige Wiederholung?', '["Nervenbahnen werden durch wiederholtes Verhalten stärker", "Aus „mach ich manchmal“ wird „so bin ich“", "Angst baut sich nicht wieder auf, und Vermeidung setzt sich nicht fest", "Alle oben genannten"]'::jsonb, 'Regelmäßiges Üben sichert deine Fortschritte und verhindert, dass Fähigkeiten verkümmern. Bleib dran.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e6b9ff5d-fc7a-4e92-91d3-57411235152b', 'de', 'Was passiert psychologisch bei langen Übungspausen?', '["Die Fähigkeiten werden noch stärker", "Vermeidung und Angst haben Zeit, sich festzusetzen", "Die Nervenbahnen bleiben effizient", "Der Fortschritt vervielfacht sich von selbst"]'::jsonb, 'Pausen geben dem Kopf Raum, neue Gründe zu finden, nichts zu tun.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dd2cece1-3524-4319-bd95-d773079fa01b', 'de', 'Was hilft dir, auf Dauer dranzubleiben?', '["Dir ein realistisches Wochenminimum setzen", "Warten, bis du dich selbstbewusst fühlst", "Lange Pausen zwischen den Wiederholungen vermeiden", "Auch kleine Begegnungen als vollwertige Übung zählen"]'::jsonb, 'Schwung zählt mehr als Intensität. Fortschritt entsteht durch Beständigkeit, nicht durch Kraftakte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3529af51-9b76-41c8-868a-2a04a415dc15', 'de', 'Was passiert, wenn aus „ich übe etwas“ ein „ich bin jemand, der das tut“ wird?', '["Das Verhalten wird untrennbar Teil deines Selbstbilds", "Du brauchst keine Bestätigung von außen mehr, dass du es kannst", "Aus „etwas, das ich tue“ wird „wer ich bin“", "Du brauchst keinen Mut mehr, weil es keine Lücke mehr zu überwinden gibt"]'::jsonb, 'Untrennbar Teil von dir, aus „etwas, das ich tue“ wird „wer ich bin“, keine Lücke mehr, die Mut braucht: Das ist der Wandel deiner Identität.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('242a1957-a048-451a-9da7-8ab630640b24', 'de', 'Warum „braucht“ Ansprechen „keinen Mut“ mehr, wenn es dir in Fleisch und Blut übergegangen ist?', '["Du hast es so oft gemacht, dass die Angst komplett weg ist", "Es gibt keine Lücke mehr zwischen dem, wer du bist, und dem, was du tust", "Das Selbstbewusstsein aus wiederholtem Erfolg beseitigt jedes Zögern", "Du bist so gut geworden, dass das Ergebnis keine Rolle mehr spielt"]'::jsonb, 'Du kämpfst nicht gegen deine Natur an. Du zeigst einfach, wer du bist.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('371a7413-becb-4f2b-a50d-96a6e2786c70', 'de', 'Was zeichnet die Haltung des Experimentierens beim Lernen aus?', '["Jede Begegnung als Auftritt sehen", "Erfolg am Ergebnis messen", "Begegnungen als Datensammlung sehen", "Abfuhren vermeiden"]'::jsonb, 'Jede Begegnung ist nützlich, weil sie dir zeigt, was du nächstes Mal anders machen kannst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8a3d26a9-590a-4af0-95f0-d6c8c35f7896', 'de', 'Du versuchst es mit Humor, und zweimal kommt er nicht an. Was rät dir die Haltung des Experimentierens?', '["Humor ist nichts für dich", "Hör auf, Leute anzusprechen", "Lern bessere Witze auswendig", "Probier eine andere Art von Humor oder eine andere Situation"]'::jsonb, 'Jede Begegnung zeigt dir, was du nächstes Mal anders machen kannst, auch wenn sie nicht gut läuft.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28e0261e-75cb-4bdc-917c-8d6e653f374a', 'de', 'Wie nimmt die Haltung des Experimentierens einer Abfuhr den Schmerz?', '["Sie knüpft dein Ego an jedes Ergebnis", "Sie sieht Begegnungen als Datensammlung", "Sie sieht eine Abfuhr als wertvolle Information"]'::jsonb, 'Ergebnisse werden zu Lernchancen statt zu Beweisen für deinen Wert.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0d642fd6-f52e-4ce4-95a1-e14b1034c645', 'de', 'Warum verbessert Echtheit die Verbindung?', '["Sie garantiert Anziehung", "Sie senkt die Nervosität", "Sie macht im Kopf Platz für Zuhören und Feingefühl", "Sie verhindert Abfuhren"]'::jsonb, 'Wenn du aufhörst zu schauspielern, kannst du dich wirklich einlassen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b8b12ca4-eea8-4651-a0ba-a39ced8e6aef', 'de', 'Du bist von Natur aus ruhig und aufmerksam. Welcher Flirtstil passt am besten zu dir?', '["Schnelle Witze und Schlagabtausch", "Lange Erklärungen", "Pausen und ruhiger Blickkontakt", "Ständig Komplimente machen"]'::jsonb, 'Wie du Spannung erzeugst, sollte zu deinem Temperament passen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('30871b25-0072-4ec6-a580-9ac5cb667148', 'de', 'Warum funktioniert dein eigener Stil besser als übernommene Techniken?', '["Er macht im Kopf Platz für echte Verbindung", "Er passt zu den Stärken deiner Persönlichkeit", "Er verlangt, dass du dich verstellst, um die Rolle durchzuhalten"]'::jsonb, 'Echtheit kostet weniger Mühe und nutzt, was bei dir ohnehin schon funktioniert.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3d6c847d-5687-4a4a-a269-96782bfa828d', 'de', 'Deine Ansprachen enden oft schnell mit höflichen Antworten. Wo liegt dein Knackpunkt?', '["Gut einsteigen, um Interesse zu wecken", "Körperlich weitergehen", "Lange Gespräche führen", "Gut zum Abschluss kommen"]'::jsonb, 'Die Ergebnisse ändern sich, wenn du gezielt das schwächste Glied der Begegnung übst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('53171673-bc87-47f9-a580-371caf722388', 'de', 'Du steigst gut ein und unterhältst dich mühelos, aber es bleibt platonisch. Wo liegt dein Knackpunkt?', '["Beim Einstieg", "Beim Gesprächsfluss", "Dabei, Flirtspannung oder Verspieltheit reinzubringen", "Beim Abschluss"]'::jsonb, 'Die Ergebnisse ändern sich, wenn du gezielt das schwächste Glied der Begegnung übst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4195d2ca-e36c-4bd9-bb7e-e178e5d589ca', 'de', 'Du fängst Gespräche gut an, aber sie werden schnell peinlich. Wo liegt dein Knackpunkt?', '["Den Gesprächsfluss halten und sie dabeihalten", "Opener rüberbringen", "Zum Abschluss kommen und Nummern bekommen", "Körperlich weitergehen"]'::jsonb, 'Die Ergebnisse ändern sich, wenn du gezielt das schwächste Glied der Begegnung übst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b31c3930-629e-4aab-974a-035d198918d4', 'de', 'Wie findest du deine Schwachstellen zuverlässig heraus?', '["Davon ausgehen, dass es am allgemeinen Selbstbewusstsein liegt", "Beobachten, wo es in deinen Begegnungen immer wieder hakt", "Muster anschauen, wo die Dinge regelmäßig auseinanderfallen"]'::jsonb, 'Knackpunkte zeigen sich in bestimmten Momenten, in denen es immer wieder hakt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e977c9fd-3fd5-421d-b9c4-259a05b8af45', 'de', 'Was kann helfen, ein Plateau zu durchbrechen?', '["Den Schwierigkeitsgrad bewusst erhöhen", "Die Umgebung wechseln", "Eine lange Pause machen, um wieder motiviert zu sein", "Dich auf eine bestimmte kleine Fähigkeit konzentrieren"]'::jsonb, 'Neue Herausforderungen erzwingen Anpassung und Fortschritt. Lange Pausen verstärken das Vermeiden.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('07805ac1-99db-4876-9227-20fb20fbcd1f', 'de', 'Was hilft dir, geheimnisvoll zu wirken?', '["Geschichten erzählen, ohne jedes Detail zu erklären", "Dich im Gespräch nach und nach zeigen", "Tiefe andeuten, ohne deinen ganzen Lebenslauf auszubreiten", "Alle oben genannten"]'::jsonb, 'Etwas Geheimnisvolles hält die Aufmerksamkeit wach, weil es Raum für Neugier und Entdeckung lässt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('09518935-f277-43f0-8803-f6f2caa97eee', 'de', 'Was ist die „Haltung des Experimentierens“?', '["Verschiedene Herangehensweisen testen, um herauszufinden, was am besten funktioniert", "Jedes Ergebnis als Datensammlung sehen", "Weg von „Hab ich’s geschafft oder nicht?“ hin zu „Was hab ich gelernt?“", "Alle oben genannten"]'::jsonb, 'Solange du etwas daraus lernst, war die Begegnung ein Erfolg.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0b4d034c-f347-48a4-bf5e-2826500c82c6', 'de', 'Du testest einen neuen Opener, und daraus entsteht ein tolles Gespräch. Was solltest du als Nächstes tun?', '["Davon ausgehen, dass er immer funktioniert, und nie etwas ändern", "Dir merken, was funktioniert hat, und Varianten testen, um ihn zu verfeinern", "Es als Beweis nehmen, dass du jetzt perfekt bist", "Aufhören zu experimentieren, weil es geklappt hat"]'::jsonb, 'Auch Erfolg ist eine Information. Nutz ihn, um weiterzulernen und dich anzupassen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('142d920d-753e-4fc3-9a34-043fbf2cb37d', 'de', 'Welche Signale für niedrigen Status wirken sich in sozialen Umgebungen auf die Anziehung aus?', '["Allein an der Wand oder am Rand des Raums stehen", "Dich ungeschickt in Gespräche drängen", "Kaum etwas zum Gespräch beitragen oder mit niemandem reden", "Alle oben genannten"]'::jsonb, 'Signale für niedrigen Status entstehen durch Rückzug, einen ungeschickten Einstieg oder fehlende Beteiligung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1c3b9eb2-3e17-4722-a2ee-0b94061906e1', 'de', 'Vor dem Ansprechen bist du sehr nervös. Was hat Vorrang?', '["Mehr Techniken lernen, um deinen Opener zu perfektionieren", "Dich stundenlang mental vorbereiten", "Warten, bis die Nervosität nachlässt", "Heute eine kleine Begegnung machen, egal wie sie ausgeht"]'::jsonb, 'Wenn du dich oft der Situation stellst, gewöhnt sich dein Nervensystem daran, dass sie sicher ist.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e482ecd-547c-44e9-96d0-74c25f5ef813', 'de', 'Frauen reden gern mit dir, flirten aber nie zurück. Wo liegt dein Knackpunkt?', '["Sympathisch und freundlich sein", "Flirtspannung oder Verspieltheit reinbringen", "Dass die erste Ansprache angenommen wird", "Dich nach dem Nummerntausch melden"]'::jsonb, 'Die Ergebnisse ändern sich, wenn du gezielt das schwächste Glied der Begegnung übst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28e3345b-49dd-42c7-86fd-931c5c032deb', 'de', 'Du bist von Natur aus ruhig und nachdenklich. Welcher Flirtstil passt am besten zu dir?', '["Pausen, direkter Blickkontakt und überraschende Fragen", "Laute, energiegeladene, mutige Sprüche", "Die Witze eines lustigen Coaches kopieren", "Krampfhaft direkte Komplimente machen"]'::jsonb, 'Setz die Prinzipien mit deiner eigenen Persönlichkeit um, dann entsteht echte Verbindung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('324d0f15-f4f3-4d1e-aa8a-9a3dbbda9f55', 'de', 'Wie verändern Gruppenaktivitäten deine Chancen, Leute kennenzulernen?', '["Sie garantieren sofort neue Kontakte", "Sie sorgen für regelmäßigen Kontakt und mögliche Brücken zu neuen Leuten", "Sie halten deine Welt klein und vorhersehbar"]'::jsonb, 'Gruppen bringen viele Begegnungen und Kontakte über Umwege, und daraus entstehen ganz natürlich Gelegenheiten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('360f9f51-86bf-4779-ab39-a8155afc9bdd', 'de', 'Warum erzeugt es mehr Anziehung, nur ausgewählt etwas von dir zu erzählen, statt alles preiszugeben?', '["Es überschüttet sie mit Informationen", "Es lässt Lücken, die neugierig machen", "Es lädt ihre Fantasie ein, die Lücken zu füllen"]'::jsonb, 'Etwas Geheimnisvolles regt zum Nachdenken an, und das Entdecken wird schrittweise und spannend.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4826161e-e13f-4b37-8fe4-6ee85878fd7e', 'de', 'Welche Veränderung in deiner Einstellung brauchst du, um mehr Gelegenheiten zu schaffen?', '["Bewusst mehr soziale Kontakte in den Alltag einbauen", "Zu neuen Aktivitäten Ja sagen, auch wenn du unsicher bist", "Erwarten, dass jede Mühe sofort Ergebnisse bringt"]'::jsonb, 'Regelmäßiges Handeln erweitert deine Welt, und so entstehen Gelegenheiten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48fe4298-aeef-4a2e-85e5-f1d2e2592692', 'de', 'Was ermöglicht dir die Haltung des Experimentierens?', '["Scheitern, ohne dich als Versager zu fühlen", "Aus Erfahrungen lernen, statt sie zu bewerten", "Eine Sammlung aufbauen, was in welcher Situation funktioniert", "Alle oben genannten"]'::jsonb, 'Wenn du jedes Ansprechen als Experiment siehst, wird eine Abfuhr zu einer Information statt zu einem Versagen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51e669d2-f554-48ce-843b-4c367370982e', 'de', 'Warum macht häufiges Ansprechen dich weniger nervös?', '["Es bringt bessere Sprüche", "Es trainiert dein Nervensystem durch Gewöhnung", "Die gefühlte Bedrohung sinkt mit der Zeit", "Logik ersetzt die Angst durch Selbstbewusstsein"]'::jsonb, 'Nervosität verschwindet, wenn du dich immer wieder sicheren Situationen stellst, nicht durch Nachdenken oder Vorbereitung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5eb79a5b-9ac8-45c2-9e9d-423d1d2916e4', 'de', 'Auf deinen Opener kommt eine höfliche, aber flache Antwort. Was solltest du denken?', '["„Der Opener kam nicht an. Was kann ich nächstes Mal anders machen?“", "„Ich hab versagt und bin schlecht darin.“", "„Sie hatte eh kein Interesse.“", "„Ich sollte heute aufhören, Leute anzusprechen.“"]'::jsonb, 'Schau dir die Einflussfaktoren an, damit du nützliche Infos für die nächsten Versuche sammelst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5feee0d2-d777-41cf-a17b-4a10cdba7c30', 'de', 'Warum hilft dir ein interessantes Leben bei der Anziehung?', '["Eigene Anziehungskraft: Menschen fühlen sich ganz natürlich zu dir hingezogen", "Gesprächsstoff, der ganz natürlich fließt", "Beides"]'::jsonb, 'Ein interessantes Leben bringt echte Erlebnisse hervor, und die ziehen Menschen ganz natürlich an.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('609555df-ed41-4234-bb64-85b739483e7a', 'de', 'Welche Aktivitäten bringen dich regelmäßig mit neuen Leuten zusammen?', '["Fitnesskurse in der Gruppe mit festen Zeiten", "Im Café arbeiten statt zu Hause", "Hobbygruppen, die sich regelmäßig treffen, etwa zum Laufen oder Kochen", "Alle oben genannten"]'::jsonb, 'Wenn du dich bewusst oft unter Leute begibst, entstehen Möglichkeiten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('63f71c1b-3eab-460c-91fa-a52c22044efb', 'de', 'Woran merkt man, dass ein Mann ein Leben jenseits der Arbeit hat?', '["Er erwähnt, was er gerade lernt oder woran er arbeitet", "Er spricht neugierig über die Welt", "Er vermeidet es, über sich zu reden", "Er hat Geschichten aus einem erfüllten Leben"]'::jsonb, 'Gelebte Erfahrungen zeigen sich ganz natürlich daran, wie jemand redet.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6cbe70b0-30ea-4012-9096-6f2a5efad2ed', 'de', 'Warum ist sozialer Status am Anfang ein so starkes Signal für Anziehung?', '["Er zeigt direkt Reichtum oder Berühmtheit", "Die positiven Reaktionen anderer zeigen, dass man gern mit dir Zeit verbringt", "Menschen vertrauen darauf, was die Gruppe attraktiv findet"]'::jsonb, 'Status zeigt, wie dein Umfeld dich schätzt, und das beeinflusst, wie offen sie für dich ist.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79d8a1ab-f362-4b54-96da-46e704c946f6', 'de', 'Welche Signale senken in einer Location deinen wahrgenommenen sozialen Status?', '["Am Rand des Raums herumstehen", "Von mehreren Leuten herzlich begrüßt werden", "Erzwungene oder abrupte Ansprachen", "Sichtbar wohl in der Umgebung sein"]'::jsonb, 'Ein ungünstiger Platz und erzwungene Kontakte zeigen, dass du nicht richtig dazugehörst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('835a240c-8530-4ebc-a1a2-6750a3953290', 'de', 'Du kannst Menschen gut das Gefühl geben, gehört zu werden. Worauf könntest du setzen?', '["Energiegeladenen Schlagabtausch", "Lautes Geschichtenerzählen", "Direkte, mutige Komplimente", "Tiefe Fragen und aktives Zuhören"]'::jsonb, 'Nutz deine natürliche Stärke, um auf echte Weise eine Verbindung aufzubauen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('929ddae6-c1d3-4185-b3f1-b34b2eb34346', 'de', 'Du bist von Natur aus intensiv und direkt. Welcher Flirtstil passt am besten zu dir?', '["Lockerer Schlagabtausch und alberne Witze", "Starker Blickkontakt mit gezielten Worten und Pausen", "Lange Geschichten und indirekte Andeutungen", "Übertrieben höfliche Zustimmung"]'::jsonb, 'Setz die Prinzipien mit deiner eigenen Persönlichkeit um, dann entsteht echte Verbindung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95566af1-be99-4506-bdd8-59bc1224aa22', 'de', 'Wovor schützt dich Dranbleiben vor allem?', '["Vor fehlender Motivation", "Vor einem Plateau", "Davor, dass die Angst zurückkommt und sich Vermeidung festsetzt", "Vor sozialer Ablehnung"]'::jsonb, 'Regelmäßiges Üben sichert deine Fortschritte und verhindert, dass Fähigkeiten verkümmern. Bleib dran.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('971392d7-a116-4cf8-b454-2526464b795a', 'de', 'Warum macht häufiges Ansprechen dich mit der Zeit weniger nervös?', '["Das Nervensystem gewöhnt sich an Vertrautes", "Durch Gewöhnung lernt der Körper, dass es sicher ist", "Wiederholte Konfrontation schwächt die Bedrohungsreaktion", "Alle oben genannten"]'::jsonb, 'Regelmäßige Wiederholung baut die Angst durch Erfahrung ab.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('98fd5abd-0203-4c21-bbff-f869372f2335', 'de', 'Was signalisiert in einer Umgebung hohen sozialen Status?', '["Leute suchen deine Nähe und beziehen dich in Gespräche ein", "Andere reden herzlich und gern mit dir", "Du bewegst dich entspannt durch den Raum, nicht unbeholfen", "Alle oben genannten"]'::jsonb, 'Hoher Status zeigt sich an Leichtigkeit, daran, dass du einbezogen wirst, und daran, wie andere ganz natürlich auf dich reagieren.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('99d720d0-bfa1-45ff-a43b-49f9f15f631e', 'de', 'Warum fühlt sich Ansprechen mit der Zeit leichter an, wenn du dranbleibst?', '["Die Nervenbahnen werden effizienter", "Das Gehirn stuft das Verhalten als normal ein", "Logik beseitigt die Angst"]'::jsonb, 'Wiederholung stärkt die Nervenbahnen und verändert dein Selbstbild, und es kostet weniger Mühe.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('afbf1b2d-da55-4722-9e2b-7044a65e1227', 'de', 'Du sprichst nur am Wochenende an, in Situationen mit viel Druck. Was riskierst du damit?', '["Schnellere Gewöhnung durch die Intensität", "Sofort weniger Nervosität", "Schnell starke Fähigkeiten aufzubauen", "Langsamen Fortschritt, weil du dich zu selten der Situation stellst"]'::jsonb, 'Seltene Wiederholungen halten die Situation fremd, und die Nervosität bleibt länger hoch.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b1dad7ff-1e71-4b22-b734-b1ca8f1c8973', 'de', 'Woran merkst du, dass dein Freundeskreis dich in deiner Entwicklung bremst?', '["Sie machen sich über deine Versuche lustig, neue Leute kennenzulernen", "Sie meiden ständig soziale Situationen", "Sie ermutigen eher zur Bequemlichkeit als zum Handeln", "Sie unterstützen kleine Risiken, die du eingehst"]'::jsonb, 'Ein Umfeld, in dem Ausweichen normal ist, lässt dein Selbstbewusstsein still und leise schrumpfen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b72f662b-1295-4658-bb7a-cf26f14aea82', 'de', 'Wie kannst du Status aufbauen?', '["Ganz natürlich mit den Leuten im Raum ins Gespräch kommen", "Dich entspannt durch den Raum bewegen", "Bei Gesprächen mitmachen und etwas beitragen", "Dich absondern, um geheimnisvoll zu wirken"]'::jsonb, 'Echtes Engagement im Miteinander zeigt, dass andere gern Zeit mit dir verbringen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bfac329b-b9e4-4dbf-9045-786f91c69c40', 'de', 'Du bist von Natur aus warmherzig und einfühlsam. Welcher Flirtstil passt am besten zu dir?', '["Tiefe, neugierige Fragen, die echtes Interesse zeigen", "Aggressive, mutige Sprüche", "Laute Energie und schnelles Necken", "Persönliche Themen ganz vermeiden"]'::jsonb, 'Setz die Prinzipien mit deiner eigenen Persönlichkeit um, dann entsteht echte Verbindung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c3ffa6e0-05e2-488d-a7f5-392b781d19f9', 'de', 'Du bleibst lieber zu Hause, weil es leichter ist. Was ist der versteckte Preis?', '["Weniger Chancen, Leute kennenzulernen", "Weniger Produktivität", "Verlorene Energie", "Niedrigere Ansprüche"]'::jsonb, 'Bequemlichkeit tauscht kurzfristige Leichtigkeit gegen langfristige Isolation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d089015f-4147-45d7-a8b2-91b48d80f944', 'de', 'Warum hilft es nicht gegen die Nervosität beim Ansprechen, bestimmte Techniken zu lernen?', '["Techniken funktionieren nicht", "Nervosität ist irrational", "Im Alarmzustand des Nervensystems kommst du an dein Wissen nicht heran", "Selbstbewusstsein kann man nicht lernen"]'::jsonb, 'Nervosität verschwindet, wenn du dich immer wieder sicheren Situationen stellst, nicht durch Nachdenken oder Vorbereitung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d5674fd6-bd0f-4780-bb0b-5afca3a759d9', 'de', 'Was ist das Hauptziel, wenn du mehr Gelegenheiten schaffst, Leute kennenzulernen?', '["Erzwingen, dass jedes Ausgehen zu einem Date führt", "Regelmäßig mit neuen Leuten in Kontakt kommen", "Öfter unter Leute gehen, damit sich ganz natürlich Gelegenheiten ergeben"]'::jsonb, 'Wenn du dich bewusst oft unter Leute begibst, entstehen Möglichkeiten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d8b68638-1540-4aa1-a96a-3d316ea102b3', 'de', 'Wie hilft dir dein Freundeskreis beim Ansprechen und Kennenlernen?', '["Freunde können dich ermutigen zu handeln", "Dein Umfeld kann es leichter machen, mutig zu sein", "Deine Freunde können dir Gelegenheiten verschaffen, neue Leute kennenzulernen", "Alle oben genannten"]'::jsonb, 'Dein Umfeld fördert entweder deine Entwicklung oder bestärkt dein Zögern.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('db1590aa-6103-4532-bff1-7bcf8930cfef', 'de', 'Welches Verhalten bewahrt im Gespräch etwas Geheimnisvolles?', '["Fragen beantworten, ohne zu viel zu erklären", "Früh alles erzählen, um offen zu sein", "Tiefe nach und nach zeigen", "Raum für Nachfragen lassen"]'::jsonb, 'Bei etwas Geheimnisvollem geht es ums Tempo, nicht ums Verschweigen oder Ausweichen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('db1e61cd-85f6-4787-a686-1e10e72ffe10', 'de', 'Was in deinem Leben macht Gespräche ganz natürlich leichter und spannender?', '["Hobbys oder Fähigkeiten, an denen du dranbleibst", "Neugier auf neue Erfahrungen", "Darauf warten, dass die richtige Person Spannung in dein Leben bringt", "Projekte, an denen du aktiv arbeitest"]'::jsonb, 'Ein interessantes Leben liefert mühelos Gesprächsstoff.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dda0749c-c9ba-4e4a-affe-2eb786b6ec12', 'de', 'Warum ist ein interessantes Leben mehr als nur oberflächlicher Charme?', '["Es liefert echte Geschichten und Gesprächsstoff", "Es zeigt, dass du eine eigene Welt hast, unabhängig von Beziehungen", "Es beruht allein auf beeindruckenden Leistungen"]'::jsonb, 'Ein interessantes Leben bringt echte Erlebnisse hervor, und die ziehen Menschen ganz natürlich an.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e2c71b43-3067-41f1-9745-de39c9164feb', 'de', 'Du bist von Natur aus witzig. Welcher Flirtstil passt am besten zu dir?', '["Humor und verspieltes Necken einbauen", "Intensiven Blickkontakt und Pausen einsetzen", "Mutige, direkte Sprüche machen", "Komplett ernst bleiben"]'::jsonb, 'Nutz die Stärke deines Humors, um auf deine eigene Art Spannung zu erzeugen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e310c934-f43c-49b6-b568-70a8a9baf70c', 'de', 'Welche Ergebnisse zählen mit der Haltung des Experimentierens trotzdem als Fortschritt?', '["Eine klare Abfuhr", "Eine neutrale Reaktion", "Ein kurzes Gespräch", "Alle oben genannten"]'::jsonb, 'Solange du etwas daraus lernst, war die Begegnung ein Erfolg.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e3d69b71-e0dd-4f11-b25f-ecc126cd2696', 'de', 'Ein Ansprechen endet schnell, und sie war kaum dabei. Worauf solltest du dich danach konzentrieren?', '["Darauf, dass es beweist, dass du nicht gut genug bist", "Ähnliche Situationen zu vermeiden", "Welche Faktoren du anders testen kannst: Timing, Energie, Opener", "Darauf, dass es nächstes Mal sofort klappen muss"]'::jsonb, 'Schau dir die Einflussfaktoren an, damit du nützliche Infos für die nächsten Versuche sammelst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f3ef742e-f78a-42cd-a813-76571d61bce5', 'de', 'Warum steigert etwas Geheimnisvolles die Anziehung?', '["Du wirkst dadurch unerreichbar", "Ihre Fantasie bekommt etwas zum Arbeiten", "Es versteckt Unsicherheit", "Es verhindert emotionale Verbindung"]'::jsonb, 'Neugier entsteht durch unvollständige Informationen. Etwas Geheimnisvolles hält sie gedanklich dabei.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
